    "01_owner/OPR_Building_4410_RevB.docx",
    "01_owner/_superseded/OPR_Building_4410_RevA.docx",
    "01_owner/IES-26_Fort_Calder_Installation_Electrical_Design_Standard_Rev4.pdf",
]:
    p = os.path.join(base, rel)
    print("==========================================")
