    dxf = ezdxf.readfile(os.path.join(base, rel))
    for blk in dxf.blocks:
        if not blk.name.startswith('*'):
            print("Block:", blk.name)
            for e in blk:
                if e.dxftype() in ('TEXT', 'MTEXT', 'ATTRIB', 'ATTDEF'):
                    print("  ", e.dxftype(), getattr(e.dxf, 'text', getattr(e, 'text', '')))
    msp = dxf.modelspace()
    items = []
    for e in msp:
        if e.dxftype() in ('TEXT', 'MTEXT'):
            t = e.dxf.text if e.dxftype() == 'TEXT' else e.text
            items.append((round(e.dxf.insert.x, 1), round(e.dxf.insert.y, 1), t))
        elif e.dxftype() == 'INSERT':
            items.append((round(e.dxf.insert.x, 1), round(e.dxf.insert.y, 1), f"INSERT:{e.dxf.name}"))
    for x, y, t in sorted(items, key=lambda k: (-k[1], k[0])):
        print(f"({x:6.1f}, {y:6.1f}) {t}")
