import os, re, xml.etree.ElementTree as ET

base = "/filesystem/final_batch4__electrical_task8_electrical_specs__blind"

def full_text(el):
    if el is None: return ""
    return "".join(el.itertext()).strip()

for sec in ["26 05 73", "26 20 00", "26 24 13", "26 32 15", "26 36 23", "26 51 00"]:
    p = os.path.join(base, f"20_guide_specifications/UFGS_Division_26_SpecsIntact/{sec}.SEC")
    with open(p, encoding='cp1252') as f:
        xml_str = f.read()
    root = ET.fromstring(xml_str)
    # Remove NTE and non-Army TAI
    def clean(elem):
        for ch in list(elem):
            if ch.tag in ('HDR', 'NTE', 'MTA'):
                elem.remove(ch)
            elif ch.tag == 'TAI':
                opt = ch.attrib.get('OPT', '').upper()
                if 'ARMY' not in opt and 'USACE' not in opt:
                    elem.remove(ch)
                else:
                    clean(ch)
            else:
                clean(ch)
    clean(root)
    print("==========================================")
    print(f"SECTION {sec}: {full_text(root.find('STL'))}")
    for prt_i, prt in enumerate(root.findall('PRT'), 1):
        for spt_i, spt in enumerate(prt.findall('SPT'), 1):
            t1 = full_text(spt.find('TTL'))
            txt1 = full_text(spt)
            brks = re.findall(r'\[[^\]]*\]', txt1)
            print(f"  {prt_i}.{spt_i} {t1} (brackets: {len(brks)})")
            for sb1_i, sb1 in enumerate(spt.findall('SPT'), 1):
                t2 = full_text(sb1.find('TTL'))
                b2 = re.findall(r'\[[^\]]*\]', full_text(sb1))
                print(f"    {prt_i}.{spt_i}.{sb1_i} {t2} (brackets: {len(b2)})")
