python3 - << 'EOF'
import os, re, xml.etree.ElementTree as ET

base = "/filesystem/final_batch4__electrical_task8_electrical_specs__blind"

def dump_sec(sec_num):
    p = os.path.join(base, f"20_guide_specifications/UFGS_Division_26_SpecsIntact/{sec_num}.SEC")
    with open(p, encoding='cp1252') as f:
        xml_str = f.read()
    root = ET.fromstring(xml_str)
    def clean(elem):
        for ch in list(elem):
            if ch.tag in ('HDR', 'NTE', 'MTA', 'MET'):
                elem.remove(ch)
            elif ch.tag == 'TAI':
                opt = ch.attrib.get('OPT', '').upper()
                if 'ARMY' not in opt and 'USACE' not in opt and 'DESIGN-BID-BUILD' not in opt:
                    if any(x in opt for x in ['NAVY', 'NAVFAC', 'AIR FORCE', 'AFCEC', 'DESIGN-BUILD', 'NASA']):
                        elem.remove(ch)
                        continue
                clean(ch)
            else:
                clean(ch)
    clean(root)

    def text_of(el):
        return re.sub(r'\s+', ' ', "".join(el.itertext())).strip()

    print("==========================================================")
    print(f"SECTION {sec_num}: {text_of(root.find('STL'))}")
    for prt_i, prt in enumerate(root.findall('PRT'), 1):
        for spt_i, spt in enumerate(prt.findall('SPT'), 1):
            t1 = text_of(spt.find('TTL'))
            if t1 == 'REFERENCES': continue
            print(f"\n--- {prt_i}.{spt_i} {t1} ---")
            # print direct text and sub-SPTs
            for sb1_i, sb1 in enumerate(spt.findall('SPT'), 1):
                t2 = text_of(sb1.find('TTL'))
                print(f"  [{prt_i}.{spt_i}.{sb1_i} {t2}]")
